verify_package(rvest)

retrieve_bls_industry_codes &lt;- function(){
    filename &lt;- file.path("data", "mp02", "bls_industry_classifications.csv")

    if(!file.exists(filename)){
        response &lt;- request("https://www.bls.gov") |&gt; 
            req_url_path("cew", "classifications", "industry", "industry-titles.htm") |&gt;
            req_headers(`User-Agent` = "Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:143.0) Gecko/20100101 Firefox/143.0") |&gt; 
            req_error(is_error = \(resp) FALSE) |&gt;
            req_perform()

        resp_check_status(response)

        naics_classification &lt;- resp_body_html(response) |&gt;
            html_element("#naics_titles") |&gt; 
            html_table() |&gt;
            mutate(title = str_trim(str_remove(str_remove(`Industry Title`, Code), "NAICS"))) |&gt;
            select(-`Industry Title`) |&gt;
            mutate(depth = if_else(nchar(Code) &lt;= 5, nchar(Code) - 1, NA)) |&gt;
            filter(!is.na(depth))

        naics_classification &lt;- naics_classification |&gt; 
            filter(depth == 4) |&gt; 
            rename(level4_title=title) |&gt; 
            mutate(level1_code = str_sub(Code, end=2), 
                   level2_code = str_sub(Code, end=3), 
                   level3_code = str_sub(Code, end=4)) |&gt;
            left_join(naics_classification, join_by(level1_code == Code)) |&gt;
            rename(level1_title=title) |&gt;
            left_join(naics_classification, join_by(level2_code == Code)) |&gt;
            rename(level2_title=title) |&gt;
            left_join(naics_classification, join_by(level3_code == Code)) |&gt;
            rename(level3_title=title) |&gt;
            select(-starts_with("depth")) |&gt;
            rename(level4_code = Code) |&gt;
            select(level1_title, level2_title, level3_title, level4_title, 
                   level1_code,  level2_code,  level3_code,  level4_code)

        write_csv(naics_classification, filename)
    }

    read_csv(filename, show_col_types=FALSE)
}

INDUSTRY_CLASSIFICATIONS &lt;- retrieve_bls_industry_codes()




