# NOTE: This chunk is set to eval: false to allow document rendering without BLS data
# The BLS QCEW download is very large (~1.1 GB) and takes significant time
# Set eval: true if you want to download and use this data

verify_package(httr2)
verify_package(rvest)

retrieve_bls_qcew_data &lt;- function(initial_year=2009, final_year=2023){
    filename &lt;- glue("bls_qcew_{initial_year}_{final_year}.csv.gz")
    filename &lt;- file.path("data", "mp02", filename)

    YEAR_RANGE &lt;- seq(initial_year, final_year)
    YEAR_RANGE &lt;- YEAR_RANGE[YEAR_RANGE != 2020] # Exclude Covid year to match ACS

    if(!file.exists(filename)){
        COMPLETE_DATA &lt;- map(YEAR_RANGE, .progress=TRUE, possibly(function(yr){
            file_inner &lt;- file.path("data", "mp02", glue("{yr}_qcew_annual_singlefile.zip"))

            # Verify existing file integrity
            if(file.exists(file_inner)){
                if(file.info(file_inner)$size &lt; 755e5){
                    message("Removing corrupted file for year ", yr)
                    file.remove(file_inner)
                }
            }

            # Download if needed
            if(!file.exists(file_inner)){
                message("Downloading employment data for year ", yr)
                request("https://www.bls.gov") |&gt; 
                    req_url_path("cew", "data", "files", yr, "csv",
                                 glue("{yr}_annual_singlefile.zip")) |&gt;
                    req_headers(`User-Agent` = "Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:143.0) Gecko/20100101 Firefox/143.0") |&gt; 
                    req_retry(max_tries=5) |&gt;
                    req_perform(file_inner)
            }

            # Verify download success
            if(file.info(file_inner)$size &lt; 755e5){
                stop("Download unsuccessful for year ", yr, ". File integrity check failed.")
            }

            # Process data
            read_csv(file_inner, 
                     show_col_types=FALSE) |&gt; 
                mutate(YEAR = yr) |&gt;
                select(area_fips, 
                       industry_code, 
                       annual_avg_emplvl, 
                       total_annual_wages, 
                       YEAR) |&gt;
                filter(nchar(industry_code) &lt;= 5, 
                       str_starts(area_fips, "C")) |&gt;
                filter(str_detect(industry_code, "-", negate=TRUE)) |&gt;
                mutate(FIPS = area_fips, 
                       INDUSTRY = as.integer(industry_code), 
                       EMPLOYMENT = as.integer(annual_avg_emplvl), 
                       TOTAL_WAGES = total_annual_wages) |&gt;
                select(-area_fips, 
                       -industry_code, 
                       -annual_avg_emplvl, 
                       -total_annual_wages) |&gt;
                filter(INDUSTRY != 10) |&gt;
                mutate(AVG_WAGE = TOTAL_WAGES / EMPLOYMENT)
        })) |&gt; bind_rows()

        write_csv(COMPLETE_DATA, filename)
    }

    COMPLETE_DATA &lt;- read_csv(filename, show_col_types=FALSE)

    DOWNLOADED_YEARS &lt;- unique(COMPLETE_DATA$YEAR)
    MISSING_YEARS &lt;- setdiff(YEAR_RANGE, DOWNLOADED_YEARS)

    if(length(MISSING_YEARS) &gt; 0){
        stop("Data retrieval incomplete for years: ", paste(MISSING_YEARS, collapse=", "),
             ". Please remove intermediate files and retry.")
    }

    COMPLETE_DATA
}

