Question 3: Population Ranking Comparison (2009 vs 2023)
Analysis Objective: Examine shifts in population rankings between 2009 and 2023 for metropolitan areas.


Display Q3 Analysis Code
verify_package(DT)

population_rankings &lt;- TOTAL_POPULATION |&gt;
    filter(year %in% c(2009, 2023)) |&gt;
    group_by(year) |&gt;
    mutate(ranking = rank(-population, ties.method = "first")) |&gt;
    ungroup() |&gt;
    select(GEOID, NAME, year, population, ranking) |&gt;
    pivot_wider(names_from = year, 
                values_from = c(population, ranking),
                names_sep = "_") |&gt;
    mutate(
        ranking_change = ranking_2009 - ranking_2023,
        population_change = population_2023 - population_2009,
        percent_change = (population_change / population_2009) * 100
    ) |&gt;
    arrange(desc(abs(ranking_change))) |&gt;
    head(15)

population_rankings |&gt;
    select(NAME, ranking_2009, ranking_2023, ranking_change, percent_change) |&gt;
    rename(
        "Metropolitan Area" = NAME,
        "2009 Rank" = ranking_2009,
        "2023 Rank" = ranking_2023,
        "Rank Change" = ranking_change,
        "% Growth" = percent_change
    ) |&gt;
    datatable(
        options = list(pageLength = 10, scrollX = TRUE),
        caption = "Top 15 Metropolitan Areas by Ranking Change (2009-2023)"
    ) |&gt;
    formatRound("% Growth", 1) |&gt;
    formatStyle(
        "Rank Change",
        color = styleInterval(c(-0.5, 0.5), c('#cc0000', '#666666', '#00cc66'))
    )






Key Findings: Metropolitan areas in the southern and western United States experienced substantial population growth, resulting in improved national rankings. Conversely, certain northeastern and midwestern regions showed declining rankings despite modest population increases.



Question 4: Highest Growth Rate Metropolitan Area (2009-2023)
Analysis Objective: Identify the metropolitan area with the highest percentage population growth between 2009 and 2023.


Display Q4 Analysis Code
growth_analysis &lt;- TOTAL_POPULATION |&gt;
    filter(year %in% c(2009, 2023)) |&gt;
    select(GEOID, NAME, year, population) |&gt;
    pivot_wider(names_from = year, values_from = population) |&gt;
    mutate(
        growth_rate = ((`2023` - `2009`) / `2009`) * 100
    ) |&gt;
    arrange(desc(growth_rate)) |&gt;
    head(10)








TipAnalysis Result



The fastest-growing metropolitan area from 2009 to 2023 was Gulfport-Biloxi, MS Metro Area with a remarkable 73.1% population increase.




Display Growth Chart Code
verify_package(ggplot2)

ggplot(growth_analysis, aes(x = reorder(NAME, growth_rate), y = growth_rate)) +
    geom_col(fill = "#0066cc", alpha = 0.8) +
    coord_flip() +
    labs(
        title = "Top 10 Fastest Growing Metropolitan Areas",
        subtitle = "Population Growth Rate: 2009-2023",
        x = NULL,
        y = "Percentage Growth (%)"
    ) +
    theme_minimal() +
    theme(
        plot.title = element_text(face = "bold", size = 14),
        axis.text.y = element_text(size = 9)
    )












Question 5: Aggregate Household Growth (2009-2023)
Analysis Objective: Calculate the total increase in households across all metropolitan areas from 2009 to 2023.


Display Q5 Analysis Code
household_expansion &lt;- TOTAL_HOUSEHOLDS |&gt;
    filter(year %in% c(2009, 2023)) |&gt;
    group_by(year) |&gt;
    summarise(aggregate_households = sum(households, na.rm = TRUE)) |&gt;
    pivot_wider(names_from = year, values_from = aggregate_households) |&gt;
    mutate(
        household_increase = `2023` - `2009`,
        percent_increase = (household_increase / `2009`) * 100
    )








TipAnalysis Result



Between 2009 and 2023, the total number of households across all metropolitan areas increased by 18,077,341 households, representing a 18% increase.

Rental Cost Burden

Calculating Rent Burden Index
The rent burden index quantifies housing affordability by comparing the ratio of rental costs to household income. A baseline value of 100 represents the national average for the reference period.


Display Burden Index Code
baseline_period &lt;- HOUSEHOLD_INCOME |&gt;
    filter(year %in% 2009:2012) |&gt;
    inner_join(MONTHLY_RENT |&gt; filter(year %in% 2009:2012), 
               by = c("GEOID", "NAME", "year")) |&gt;
    group_by(GEOID, NAME) |&gt;
    summarise(
        baseline_income = mean(household_income, na.rm = TRUE),
        baseline_rent = mean(monthly_rent, na.rm = TRUE),
        .groups = "drop"
    ) |&gt;
    mutate(baseline_ratio = (baseline_rent * 12) / baseline_income * 100)

national_baseline &lt;- mean(baseline_period$baseline_ratio, na.rm = TRUE)

burden_index_data &lt;- HOUSEHOLD_INCOME |&gt;
    inner_join(MONTHLY_RENT, by = c("GEOID", "NAME", "year")) |&gt;
    mutate(current_ratio = (monthly_rent * 12) / household_income * 100) |&gt;
    mutate(burden_index = (current_ratio / national_baseline) * 100)





Metropolitan Areas with Highest Rent Burden (2023)


Display Top Burden Areas Code
highest_burden_2023 &lt;- burden_index_data |&gt;
    filter(year == 2023) |&gt;
    arrange(desc(burden_index)) |&gt;
    head(15) |&gt;
    select(NAME, household_income, monthly_rent, burden_index)

highest_burden_2023 |&gt;
    rename(
        "Metropolitan Area" = NAME,
        "Median Income" = household_income,
        "Monthly Rent" = monthly_rent,
        "Burden Index" = burden_index
    ) |&gt;
    datatable(
        options = list(pageLength = 10, scrollX = TRUE),
        caption = "Top 15 Metropolitan Areas by Rent Burden Index (2023)"
    ) |&gt;
    formatCurrency(c("Median Income"), digits = 0) |&gt;
    formatCurrency(c("Monthly Rent"), digits = 0) |&gt;
    formatRound("Burden Index", 1) |&gt;
    formatStyle(
        "Burden Index",
        background = styleColorBar(highest_burden_2023$burden_index, '#ff6600'),
        backgroundSize = '100% 80%',
        backgroundRepeat = 'no-repeat',
        backgroundPosition = 'center'
    )









Burden Index Trend Analysis


Display Trend Analysis Code
verify_package(plotly)

selected_metros &lt;- c("New York", "Los Angeles", "San Francisco", 
                     "Miami", "Austin", "Seattle")

trend_data &lt;- burden_index_data |&gt;
    filter(str_detect(NAME, paste(selected_metros, collapse = "|"))) |&gt;
    mutate(metro_label = str_extract(NAME, paste(selected_metros, collapse = "|")))

trend_plot &lt;- ggplot(trend_data, aes(x = year, y = burden_index, 
                                     color = metro_label, group = metro_label)) +
    geom_line(linewidth = 1.2) +
    geom_point(size = 2.5) +
    geom_hline(yintercept = 100, linetype = "dashed", color = "gray50") +
    labs(
        title = "Rent Burden Index Evolution (2009-2023)",
        subtitle = "Selected Major Metropolitan Areas",
        x = "Year",
        y = "Burden Index (100 = baseline)",
        color = "Metropolitan Area",
        caption = "Source: US Census Bureau ACS"
    ) +
    theme_minimal() +
    theme(
        plot.title = element_text(face = "bold", size = 14),
        legend.position = "bottom"
    )

ggplotly(trend_plot)

